INSERT INTO reviews (customer_name, rating, comment, is_approved) VALUES
  ('Sarah M.',    5, 'Best breakfast spot in Sheboygan! The Combo Skillet is absolutely incredible. The staff is always so friendly and welcoming.',          true),
  ('James K.',    5, 'I''ve been coming here every Sunday for 3 years. The Eggs Benedict is perfect every single time. Real comfort food done right.',        true),
  ('Emily R.',    4, 'Wonderful little cafe with a cozy atmosphere. The Strawberry Cheesecake French Toast melts in your mouth. Definitely a regular now!',   true),
  ('Michael T.',  5, 'The coffee is fantastic and always hot, with free refills! Great place to start the morning. Service is quick even when they''re busy.', true),
  ('Lisa D.',     5, 'Brought my family here for brunch — everyone loved it! Kids especially loved the pancakes. The Gyros Plate was amazing too!',           true),
  ('Robert J.',   4, 'Great food at fair prices. The Bacon Cheeseburger at lunch is a hidden gem. Highly recommend the cheese curds as a starter!',           true),
  ('Karen W.',    5, 'The Strawberry Cheesecake French Toast is worth every penny. The Western Omelette is huge and delicious. Will be back!',                true),
  ('Tom H.',      5, 'Beef noodle soup, gyro plate — yummy! Don''t forget the fresh squeezed orange juice and coffee. Tastiest savory lunch of our trip!',   true)
